import './index.less'

import { createMembershipPriceCoupon, getMembershipPriceActiveProducts, } from "@utils/api.js"
import { createCartAndCheckout } from '@utils/index.js'
import { Decimal } from 'decimal.js'
import { formatMoney } from '@shopify/theme-currency'

// product
if (!customElements.get("membership-price-product")) {
  customElements.define("membership-price-product", class MembershipProduct extends HTMLElement {
    constructor() {
      super()

      this.sectionId = this.getAttribute('id')
      this.productsWrap = this.querySelector('[data-products-wrap]')

      if (this.productsWrap) {
        this.init()

        const debounceResizeHandler = debounce(() => {
          // 更新 this.productsWrap 的最大高度
          const expandBtn = this.productsWrap.parentElement.querySelector('[data-product-expand-button]')
          if (expandBtn.classList.contains('active')) {
            this.productsWrap.style.maxHeight = this.productsWrap.scrollHeight + 'px'
          } else {
            this.productsWrap.style = ''
          }
        }, 100)

        window.addEventListener('resize', debounceResizeHandler)
      }
    }
    connectedCallback() {
      // 定位到当前组件位置
      const membership_section_id = getUrlQueryParams('membership_section_id')
      if (membership_section_id) {
        setTimeout(() => {
          const target = document.querySelector(`membership-price-product[id=${membership_section_id}]`) || document.querySelector(`membership-price-product`)
          window.scrollTo({ top: target?.offsetTop || 0 })
        }, 1000)
      }
    }
    async init() {
      try {
        // 获取配置的所有商品
        const skuIdsDOM = this.productsWrap.querySelectorAll('[data-sku-id]')

        // 获取商品
        if (skuIdsDOM.length) {
          const variantIds = Array.from(skuIdsDOM).map(it => it.dataset.skuId)

          const data = await getMembershipPriceActiveProducts({
            shopifyShopId: window.pageInfo.shopId,
            variantIds,
          })

          // 显示DOM，并移除骨架屏
          this.productsWrap.classList.remove('!hidden')
          this.removeSkeleton()

          if (data.data.length) {
            this.renderDOM(data.data)
          } else {
            // 无数据
            this.renderNoData()
          }

          this.observe()
        } else {
          // 显示DOM，并移除骨架屏
          this.productsWrap.classList.remove('!hidden')
          this.removeSkeleton()

          // 渲染无数据
          this.renderNoData()

          this.observe()
        }
      } catch (err) {
        // 显示DOM，并移除骨架屏
        this.productsWrap.classList.remove('!hidden')
        this.removeSkeleton()

        // 渲染无数据
        this.renderNoData()

        this.observe()
      }
    }
    removeSkeleton() {
      const skeletonDOM = this.productsWrap.parentElement.querySelector('[data-skeleton-wrap]')
      skeletonDOM && this.productsWrap.parentElement.removeChild(skeletonDOM)
    }
    renderDOM(data) {
      let hasData = false
      const validSkuIds = data.map(it => it.skuId)

      // 获取配置的所有商品
      this.productsWrap.querySelectorAll('[data-sku-id]').forEach(it => {
        if (validSkuIds.includes(it.dataset.skuId)) {
          hasData = true

          const promotionPriceDOM = it.querySelector('[data-promotion-price]')
          const priceDOM = it.querySelector('[data-product-price]')
          const { originPrice, } = priceDOM.dataset
          const formatOriginPrice = new Decimal(originPrice).div(100)

          const { skuId, value, valueType, discountCode, benefitId, activeId, } = data.find(({ skuId, }) => skuId === it.dataset.skuId) || {}
          this.calcDiscountPrice(promotionPriceDOM, priceDOM, formatOriginPrice, value, valueType)

          // 点击会员价购买按钮
          const buyAtMemberPriceBtn = it.querySelector('[data-member-price-buy-button]')
          buyAtMemberPriceBtn.onclick = async (e) => {
            // 已登录
            if (window.pageInfo.customerInfo.id) {
              // 如果已经领取过了
              if (discountCode) {
                this.goToCheckout(skuId, discountCode)
              }
              // 未领取，需要创建
              else {
                const target = e.target.tagName === 'SPAN' ? e.target.parentElement : e.target
                target.classList.add('btn--loading')
                try {
                  const coupon = await createMembershipPriceCoupon({
                    shopifyShopId: window.pageInfo.shopId,
                    settingId: benefitId,
                    activeId,
                    skuId,
                  })

                  if (coupon.data) {
                    this.goToCheckout(skuId, coupon.data.discountCode, () => {
                      target.classList.remove('btn--loading')
                    })
                  }
                } catch (err) {
                  pushMessage(err.message, "warning");
                  target.classList.remove('btn--loading')
                }
              }
            }
            // 未登录
            else {
              const return_url = window.location.search ? window.location.href + `#membership_section_id=${this.sectionId}` : window.location.href + `?membership_section_id=${this.sectionId}`
              window?.jackeryLoginApp?.modalLogin({
                return_url: return_url,
                register_act: 'MB-Register',
              })
            }
          }

          // 点击原始价格购买按钮
          const buyAtOriginPriceBtn = it.querySelector('[data-member-price-origin-buy-button]')
          if(!buyAtOriginPriceBtn) return
          buyAtOriginPriceBtn.onclick = async (e) => {
            // 已登录
            this.goToCheckout(skuId, '')
          }
        } else {
          it.parentElement.removeChild(it)
        }
      })

      // 无数据
      if (!hasData) {
        this.renderNoData()
      } else {
        // 是否需要显示 View More
        this.handleViewMore()
      }
    }
    // 计算优惠价格
    calcDiscountPrice(promotionPriceDOM, priceDOM, formatOriginPrice, value, valueType) {
      // 会员价，默认为商品原价
      let memberPrice = formatOriginPrice

      // 固定减免金额
      if (valueType === 0) {
        memberPrice = new Decimal(formatOriginPrice).sub(value).toNumber()
        const priceStr = formatMoney(new Decimal(value).mul(100).toNumber(), window.pageInfo.currency.money_format)
        promotionPriceDOM && (promotionPriceDOM.innerText = priceStr.replace(/\.00$|,00$/, ''))
      }
      // 百分比减免
      else if (valueType === 1) {
        const discountPrice = new Decimal(formatOriginPrice).mul(value).div(100).toNumber()
        memberPrice = new Decimal(formatOriginPrice).sub(discountPrice).toNumber()
        promotionPriceDOM && (promotionPriceDOM.innerText = value + '%')
      }

      // 会员价
      priceDOM.innerText = formatMoney(new Decimal(memberPrice).mul(100).toNumber(), window.pageInfo.currency.money_format)
    }
    // 跳转到 checkout 页
    async goToCheckout(skuId, code, cb) {
      // 设置 cookie
      let d = new Date()
      d.setTime(d.getTime() + (7 * 24 * 60 * 60 * 1000)) // 7天
      document.cookie = `discount_code=${code};expires=${d.toGMTString()};path=/`

      // window.location.href = `/cart/${skuId}:1?traffic_source=buy_now`

      try {
        // 生成 checkout url，并跳转
        const checkoutUrl = await createCartAndCheckout([{ id: skuId, quantity: 1, properties: {}, }])
        if (checkoutUrl) {
          window.location.href = checkoutUrl
        }
      } catch(err) {
        console.log(err)
      } finally {
        setTimeout(() => {
          cb && cb()
        }, 300)
      }
    }
    // View More
    handleViewMore() {
      const validDOMs = this.productsWrap.querySelectorAll('[data-sku-id]')
      const DOMLength = validDOMs.length

      // View More 按钮
      const expandBtn = this.productsWrap.parentElement.querySelector('[data-product-expand-button]')

      if (this.isMobile()) {
        if (DOMLength > 3) {
          expandBtn.classList.remove('hidden')

          if (window.pageInfo.customerInfo.id) {
            this.productsWrap.classList.add(`max-h-${936 * 3 + 48}`)
          } else {
            this.productsWrap.classList.add(`max-h-${1016 * 3 + 48}`)
          }
        }
      } else {
        const ss = Array.from(validDOMs).map(k => k.dataset.fullRow)
        if (ss[0] === '1') {
          // 1,1
          if (ss[1] === '1') {
            this.addClassList(365 * 2 + 24, 0) // 754

            if (ss[2]) {
              expandBtn.classList.remove('hidden')
            }
          }
          // 1,0
          else {
            this.addClassList(365 + 583 + 24, 44) // 928

            if (ss[2] === '1' || ss[3] === '1' || (ss[2] && ss[3] && DOMLength > 4)) {
              expandBtn.classList.remove('hidden')
            }
          }
        }
        else if (ss[0] === '0') {
          // 0,1
          if (ss[1] === '1') {
            this.addClassList(583 + 365 + 24, 44) // 928

            if (ss[2]) {
              expandBtn.classList.remove('hidden')
            }
          }
          else {
            // 0,0,1
            if (ss[2] === '1') {
              this.addClassList(583 + 365 + 24, 44) // 928

              if (ss[3]) {
                expandBtn.classList.remove('hidden')
              }
            }
            else {
              // 0,0,0,1
              if (ss[3] === '1') {
                this.addClassList(583 + 365 + 24, 44) // 928, 972

                if (ss[4]) {
                  expandBtn.classList.remove('hidden')
                }
              }
              // 0,0,0,0
              else {
                this.addClassList(583 + 583 + 24, 88) // 1102, 1190

                // 0,0,0,0,1 或者 0,0,0,0,0,1 或者 0,0,0,0,0,0 && length > 6
                if (ss[4] === '1' || ss[5] === '1' || (ss[4] && ss[5] && DOMLength > 6)) {
                  expandBtn.classList.remove('hidden')
                }
              }
            }
          }
        }
      }

      expandBtn.onclick = (e) => {
        const target = e.target.tagName === 'I' ? e.target.parentElement : e.target
        const { viewMoreText, hideText, } = target.dataset

        if (target.classList.contains('active')) {
          target.classList.remove('active')
          this.productsWrap.style = ''
          target.innerHTML = `${viewMoreText} <i class="iconfont jackery-icon-arrow-right inline-block text-32 lg:j-text-25 -lg:j-mt-3 xl:a-text-25 -xl:a-mt-3 rotate-90"></i>`

          setTimeout(() => {
            // 更新 ga 埋码文案
            target.dataset.gaParamsButton_name = viewMoreText
          }, 200)
        } else {
          target.classList.add('active')
          this.productsWrap.style.maxHeight = this.productsWrap.scrollHeight + 'px'
          target.innerHTML = `${hideText} <i class="iconfont jackery-icon-arrow-right inline-block text-32 lg:j-text-25 -lg:j-mt-3 xl:a-text-25 -xl:a-mt-3 -rotate-90"></i>`

          setTimeout(() => {
            // 更新 ga 埋码文案
            target.dataset.gaParamsButton_name = hideText
          }, 200)
        }
      }
    }
    addClassList(pcH, offset) {
      // 已登录，则减去一个按钮高度
      const ph = window.pageInfo.customerInfo.id ? pcH - offset : pcH

      this.productsWrap.classList.add(`lg:j-max-h-${ph}`, `xl:a-max-h-${ph}`)
    }
    // 无数据
    renderNoData() {
      const { noDataText, noDataImg, } = this.productsWrap.dataset
      this.productsWrap.innerHTML = `
        <div class="w-full flex-between flex-col min-h-600 lg:flex-row px-40 pt-40 pb-20 rounded-16 gap-y-40 lg:gap-y-0 lg:j-min-h-360 lg:j-rounded-8 lg:j-px-88 lg:j-py-52 lg:j-gap-x-40 xl:a-min-h-360 xl:a-rounded-8 xl:a-px-88 xl:a-py-52 xl:a-gap-40 bg-white" data-animation-dom>
          <div class="flex-1 text-#666 lg:text-#333 font-medium text-30 leading-42 lg:j-text-20 lg:j-leading-32 xl:a-text-20 xl:a-leading-32">${noDataText}</div>
          <img class="w-470 h-320 lg:j-w-376 lg:j-h-256 xl:a-w-376 xl:a-h-256 object-cover" src="${noDataImg}" alt="">
        </div>
      `
    }
    isMobile() {
      const clientWidth = document.documentElement.clientWidth || document.body.clientWidth
      return clientWidth < 1024
    }

    observe() {
      const Observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('active')
          }
        })
      }, {
        root: null,
        rootMargin: '0px',
        threshold: 0,
      })

      const parentDOM = this.productsWrap.parentElement.parentElement
      const targetDOMs = parentDOM?.querySelectorAll('[data-animation-dom]')
      if (targetDOMs.length > 0) {
        targetDOMs.forEach(it => Observer.observe(it))
      }
    }
  })
}
